            raise ValueError(
                "max backward intermediate must be finite"
            )
        contribution = [0.0] * len(snapshot)
        for i in positions:
            contribution[i] = share
        return [(parent, contribution)]

    return Tensor._make(out_data, True, (parent,), backward_fn)

